#include <stdio.h>
#include <signal.h>
#include <string.h>

volatile sig_atomic_t ints = 0, usr1 = 0, usr2 = 0, terms = 0;

void on_signal(int sig) {
    if (sig == SIGINT) ints++;
    else if (sig == SIGUSR1) usr1++;
    else if (sig == SIGUSR2) usr2++;
    else if (sig == SIGTERM) terms++;
}

int main(void) {
    signal(SIGINT, on_signal);
    signal(SIGUSR1, on_signal);
    signal(SIGUSR2, on_signal);
    signal(SIGTERM, on_signal);

    char name[16];
    while (scanf("%15s", name) == 1) {
        if (strcmp(name, "INT") == 0) raise(SIGINT);
        else if (strcmp(name, "USR1") == 0) raise(SIGUSR1);
        else if (strcmp(name, "USR2") == 0) raise(SIGUSR2);
        else if (strcmp(name, "TERM") == 0) raise(SIGTERM);
    }
    printf("INT %d\nUSR1 %d\nUSR2 %d\nTERM %d\n", (int)ints, (int)usr1, (int)usr2, (int)terms);
    return 0;
}
